settings.css:
.water-header {
  height: 100%;
  min-height: 0;
  box-sizing: border-box;
  display: flex;
  align-items: center;
  gap: 18px;
  padding: 14px 24px;
  border-radius: 10px;
  position: relative;
  overflow: hidden;
  color: #fff;
  background: linear-gradient(110deg, #0d2538, #163850 65%, #0f4c5c);
  font-family: Inter, Roboto, Arial, sans-serif;
}

.water-header-icon {
  flex-shrink: 0;
  width: 44px;
  height: 44px;
  padding: 10px;
  background: rgba(255,255,255,.08);
  border: 1px solid rgba(255,255,255,.14);
  border-radius: 10px;
  color: #a5dce7;
  box-sizing: border-box;
}

.water-header-icon svg {
  width: 100%;
  height: 100%;
}

.water-header-content {
  position: relative;
  z-index: 2;
  min-width: 0;
}

.water-header-content h1 {
  margin: 0;
  font-size: clamp(17px, 2vw, 25px);
  font-weight: 650;
  line-height: 1.25;
  letter-spacing: -.5px;
  color: white;
}

.water-header-content p {
  margin: 8px 0 0;
  font-size: 12px;
  color: #cbd5e1;
}

.water-header-content p span {
  padding: 0 7px;
  color: #7dd3fc;
}

.water-header-decoration {
  position: absolute;
  right: 0;
  bottom: 0;
  width: 38%;
  max-width: 310px;
  color: white;
  pointer-events: none;
}

.water-header-decoration svg {
  width: 100%;
  display: block;
}

@media (max-width: 650px) {
  .water-header {
    padding: 14px 16px;
    gap: 12px;
  }

  .water-header-content h1 {
    font-size: 16px;
  }

  .water-header-decoration {
    opacity: .35;
  }
}

settings.cardCss:
.station-card {
  width: 100%;
  height: 100%;
  box-sizing: border-box;
  padding: 20px;
  background: #ffffff;
  border: 1px solid #e2e8f0;
  border-top: 4px solid #0f4c5c;
  border-radius: 12px;
  font-family: Inter, Roboto, Arial, sans-serif;
  color: #0f172a;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  gap: 18px;
}

.station-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
}

.station-id {
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 1.3px;
  color: #64748b;
}

.station-header h2 {
  margin: 5px 0 3px;
  font-size: 23px;
  font-weight: 700;
}

.station-location {
  font-size: 12px;
  color: #64748b;
}

.severity {
  background: #e6f0f3;
  color: #0f4c5c;
  border-radius: 20px;
  padding: 7px 11px;
  font-size: 11px;
  font-weight: 700;
  white-space: nowrap;
}

.station-metrics {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 10px;
}

.metric {
  background: #f4f7fa;
  padding: 12px 8px;
  border-radius: 8px;
  text-align: center;
  min-width: 0;
}

.metric span {
  display: block;
  font-size: 11px;
  color: #64748b;
  margin-bottom: 5px;
}

.metric strong {
  display: block;
  font-size: 20px;
  font-weight: 700;
  overflow-wrap: anywhere;
}

.metric small {
  font-size: 10px;
  color: #64748b;
}

.station-footer {
  border-top: 1px solid #e2e8f0;
  padding-top: 12px;
  display: flex;
  justify-content: space-between;
  gap: 8px;
  font-size: 11px;
  color: #64748b;
}

